from fractions import Fraction

def solve_exact(N):
    sum_a = Fraction(0)
    for n in range(1, N):
        a_n = Fraction(N**n)
        for k in range(1, n + 1):
            a_n /= (N + k)
        sum_a += a_n

    sum_b = Fraction(0)
    for n in range(1, N):
        b_n = Fraction(1)
        for k in range(1, n + 1):
            b_n *= (Fraction(N - k, N))
        sum_b += b_n

    return sum_a - sum_b

for N in [100, 200, 300, 400, 500, 600, 700, 800, 900, 1000, 1500, 2000, 2025]:
