def compute_S(m):
    S1 = 0
    for n in range(1, m):
        term1 = (m**n * math.factorial(m)) / math.factorial(m+n)
        S1 += term1

    S2 = 0
    for n in range(1, m):
        prod = 1
        for k in range(1, n+1):
            prod *= (1 - k/m)
        S2 += prod

    return S1 - S2

import math
for m in range(2, 10):
    print(f"m={m}, S={compute_S(m)}")
